     1→import { useState } from "react";
     2→import { useQuery, useQueryClient } from "@tanstack/react-query";
     3→import { supabase } from "@/integrations/supabase/client";
     4→import { Button } from "@/components/ui/button";
     5→import { Input } from "@/components/ui/input";
     6→import { Label } from "@/components/ui/label";
     7→import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
     8→import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
     9→import { Switch } from "@/components/ui/switch";
    10→import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
    11→import { Badge } from "@/components/ui/badge";
    12→import { toast } from "sonner";
    13→import { Plus, Pencil, Save, Trash2, Loader2, Gift, CheckCircle, AlertTriangle, Archive, RotateCcw, RefreshCw, Link2, ExternalLink } from "lucide-react";
    14→import ConfirmDialog from "./ConfirmDialog";
    15→import { logAuditAction } from "@/lib/auditLog";
    16→
    17→const parseFunctionError = (error: any) => {
    18→  const message = error?.message || "";
    19→  const jsonStart = message.indexOf("{");
    20→  if (jsonStart === -1) return null;
    21→  try {
    22→    return JSON.parse(message.slice(jsonStart));
    23→  } catch {
    24→    return null;
    25→  }
    26→};
    27→
    28→const syncDodoProduct = async (action: string, payload: any) => {
    29→  const { data, error } = await supabase.functions.invoke("manage-dodo-product", {
    30→    body: { action, type: "credit_pack", ...payload },
    31→  });
    32→
    33→  if (error) {
    34→    const parsed = parseFunctionError(error);
    35→    if (parsed?.not_found) return parsed;
    36→    throw error;
    37→  }
    38→
    39→  if (data?.not_found) return data;
    40→  if (data?.error) throw new Error(data.error);
    41→  return data;
    42→};
    43→
    44→const CreditPacksTab = () => {
    45→  const qc = useQueryClient();
    46→  const [saving, setSaving] = useState(false);
    47→  const [deleteTarget, setDeleteTarget] = useState<{ id: string; name: string; dodo_product_id?: string; dodo_credit_entitlement_id?: string; paymentCount?: number } | null>(null);
    48→  const [showArchived, setShowArchived] = useState(false);
    49→  const [verifying, setVerifying] = useState<string | null>(null);
    50→  const [verifyResults, setVerifyResults] = useState<Record<string, { exists: boolean; is_active?: boolean }>>({});
    51→
    52→  const { data: packs } = useQuery({
    53→    queryKey: ["admin_credit_packs"],
    54→    queryFn: async () => {
    55→      const { data, error } = await supabase.from("credit_packs").select("*").order("created_at");
    56→      if (error) throw error;
    57→      return data;
    58→    },
    59→  });
    60→
    61→  const { data: paymentCounts } = useQuery({
    62→    queryKey: ["admin_pack_payment_counts"],
    63→    queryFn: async () => {
    64→      const { data, error } = await supabase
    65→        .from("payments")
    66→        .select("pack_id")
    67→        .not("pack_id", "is", null);
    68→      if (error) throw error;
    69→      const counts: Record<string, number> = {};
    70→      data?.forEach((p: any) => { counts[p.pack_id] = (counts[p.pack_id] || 0) + 1; });
    71→      return counts;
    72→    },
    73→  });
    74→
    75→  const activePacks = packs?.filter((p: any) => p.active) ?? [];
    76→  const archivedPacks = packs?.filter((p: any) => !p.active) ?? [];
    77→
    78→  const [editPack, setEditPack] = useState<any>(null);
    79→  const [form, setForm] = useState({ name: "", price: "", credits: "", active: true, is_trial: false });
    80→
    81→  const openNew = () => { setForm({ name: "", price: "", credits: "", active: true, is_trial: false }); setEditPack("new"); };
    82→  const openEdit = (p: any) => { setForm({ name: p.name, price: String(p.price), credits: String(p.credits), active: p.active, is_trial: p.is_trial ?? false }); setEditPack(p); };
    83→
    84→  const validate = () => {
    85→    if (!form.name.trim()) { toast.error("Pack name is required"); return false; }
    86→    if (!form.price || parseFloat(form.price) < 0) { toast.error("Price must be 0 or greater"); return false; }
    87→    if (!form.credits || parseInt(form.credits) <= 0) { toast.error("Credits must be greater than 0"); return false; }
    88→    if (form.is_trial && form.active) {
    89→      const existingTrial = packs?.find((p: any) => p.is_trial && p.active && (editPack === "new" || p.id !== editPack?.id));
    90→      if (existingTrial) { toast.error("Only one active trial pack is allowed."); return false; }
    91→    }
    92→    return true;
    93→  };
    94→
    95→  const handleVerify = async (packId: string, productId: string) => {
    96→    setVerifying(productId);
    97→    try {
    98→      const result = await syncDodoProduct("verify", { product_id: productId });
    99→      setVerifyResults(prev => ({ ...prev, [productId]: result }));
   100→      if (result.exists && result.is_active) {
   101→        toast.success("Product verified on Dodo ✓");
   102→      } else if (result.exists) {
   103→        toast.warning("Product exists on Dodo but is inactive");
   104→      } else {
   105→        // Auto-clear stale Dodo ID from DB
   106→        await supabase.from("credit_packs").update({ dodo_product_id: null, dodo_credit_entitlement_id: null }).eq("id", packId);
   107→        qc.invalidateQueries({ queryKey: ["admin_credit_packs"] });
   108→        toast.error("Product not found on Dodo — link cleared automatically");
   109→      }
   110→    } catch (err: any) {
   111→      toast.error("Verify failed: " + (err.message || "Unknown error"));
   112→    } finally { setVerifying(null); }
   113→  };
   114→
   115→  const handleSyncToDodo = async (pack: any) => {
   116→    setSaving(true);
   117→    try {
   118→      const dodoResult = await syncDodoProduct("create", { name: pack.name, price: pack.price, credits: pack.credits });
   119→      if (dodoResult.product_id) {
   120→        const updateData: any = { dodo_product_id: dodoResult.product_id };
   121→        if (dodoResult.credit_entitlement_id) updateData.dodo_credit_entitlement_id = dodoResult.credit_entitlement_id;
   122→        await supabase.from("credit_packs").update(updateData).eq("id", pack.id);
   123→        toast.success("Pack synced with Dodo ✓");
   124→        qc.invalidateQueries({ queryKey: ["admin_credit_packs"] });
   125→      }
   126→    } catch (err: any) {
   127→      toast.error("Dodo sync failed: " + (err.message || "Unknown error"));
   128→    } finally { setSaving(false); }
   129→  };
   130→
   131→  const save = async () => {
   132→    if (!validate()) return;
   133→    setSaving(true);
   134→    try {
   135→      const payload = { name: form.name.trim(), price: parseFloat(form.price), credits: parseInt(form.credits), active: form.active, is_trial: form.is_trial } as any;
   136→
   137→      if (editPack === "new") {
   138→        const { data: inserted, error } = await supabase.from("credit_packs").insert(payload).select().single();
   139→        if (error) { toast.error(error.message); return; }
   140→        try {
   141→          const dodoResult = await syncDodoProduct("create", { name: form.name.trim(), price: parseFloat(form.price), credits: parseInt(form.credits) });
   142→          if (dodoResult.product_id) {
   143→            const updateData: any = { dodo_product_id: dodoResult.product_id };
   144→            if (dodoResult.credit_entitlement_id) updateData.dodo_credit_entitlement_id = dodoResult.credit_entitlement_id;
   145→            await supabase.from("credit_packs").update(updateData).eq("id", inserted.id);
   146→            toast.success("Credit pack saved & synced with Dodo ✓");
   147→          } else toast.success("Credit pack saved (no Dodo product ID returned)");
   148→        } catch (dodoErr: any) {
   149→          toast.warning("Pack saved locally but Dodo sync failed: " + (dodoErr.message || "Unknown error"));
   150→        }
   151→      } else {
   152→        const { error } = await supabase.from("credit_packs").update(payload).eq("id", editPack.id);
   153→        if (error) { toast.error(error.message); return; }
   154→        if (editPack.dodo_product_id) {
   155→          try {
   156→            const verification = await syncDodoProduct("verify", { product_id: editPack.dodo_product_id });
   157→
   158→            if (!verification.exists) {
   159→              await supabase.from("credit_packs").update({ dodo_product_id: null, dodo_credit_entitlement_id: null }).eq("id", editPack.id);
   160→              const recreated = await syncDodoProduct("create", {
   161→                name: form.name.trim(),
   162→                price: parseFloat(form.price),
   163→                credits: parseInt(form.credits),
   164→              });
   165→              if (recreated.product_id) {
   166→                const updateData: any = { dodo_product_id: recreated.product_id };
   167→                if (recreated.credit_entitlement_id) updateData.dodo_credit_entitlement_id = recreated.credit_entitlement_id;
   168→                await supabase.from("credit_packs").update(updateData).eq("id", editPack.id);
   169→              }
   170→              toast.success("Missing Dodo product was re-created and linked ✓");
   171→            } else {
   172→              const dodoResult = await syncDodoProduct("update", { product_id: editPack.dodo_product_id, name: form.name.trim(), price: parseFloat(form.price), credits: parseInt(form.credits) });
   173→              if (dodoResult.credit_entitlement_id) {
   174→                await supabase.from("credit_packs").update({ dodo_credit_entitlement_id: dodoResult.credit_entitlement_id }).eq("id", editPack.id);
   175→              }
   176→              toast.success("Pack updated & synced with Dodo ✓");
   177→            }
   178→          } catch (dodoErr: any) {
   179→            toast.warning("Pack updated locally but Dodo sync failed: " + (dodoErr.message || "Unknown error"));
   180→          }
   181→        } else {
   182→          try {
   183→            const dodoResult = await syncDodoProduct("create", { name: form.name.trim(), price: parseFloat(form.price), credits: parseInt(form.credits) });
   184→            if (dodoResult.product_id) {
   185→              const updateData: any = { dodo_product_id: dodoResult.product_id };
   186→              if (dodoResult.credit_entitlement_id) updateData.dodo_credit_entitlement_id = dodoResult.credit_entitlement_id;
   187→              await supabase.from("credit_packs").update(updateData).eq("id", editPack.id);
   188→              toast.success("Pack updated & linked to Dodo ✓");
   189→            } else toast.success("Pack updated");
   190→          } catch (dodoErr: any) {
   191→            toast.warning("Pack updated but Dodo link failed: " + (dodoErr.message || "Unknown error"));
   192→          }
   193→        }
   194→      }
   195→
   196→      logAuditAction(editPack === "new" ? "credit_pack.create" : "credit_pack.update", "credit_pack", editPack === "new" ? undefined : editPack.id, { name: form.name, price: form.price, credits: form.credits, is_trial: form.is_trial });
   197→      qc.invalidateQueries({ queryKey: ["admin_credit_packs"] });
   198→      setEditPack(null);
   199→    } finally { setSaving(false); }
   200→  };
   201→
   202→  const handleArchive = async (pack: any) => {
   203→    if (pack.dodo_product_id) {
   204→      try {
   205→        const v = await syncDodoProduct("verify", { product_id: pack.dodo_product_id });
   206→        if (v.exists) {
   207→          await syncDodoProduct("deactivate", { product_id: pack.dodo_product_id, credit_entitlement_id: pack.dodo_credit_entitlement_id });
   208→        } else {
   209→          await supabase.from("credit_packs").update({ dodo_product_id: null, dodo_credit_entitlement_id: null }).eq("id", pack.id);
   210→        }
   211→      } catch { /* continue */ }
   212→    }
   213→    const { error } = await supabase.from("credit_packs").update({ active: false }).eq("id", pack.id);
   214→    if (error) { toast.error(error.message); return; }
   215→    toast.success(`"${pack.name}" archived`);
   216→    logAuditAction("credit_pack.archive", "credit_pack", pack.id, { name: pack.name });
   217→    qc.invalidateQueries({ queryKey: ["admin_credit_packs"] });
   218→  };
   219→
   220→  const handleRestore = async (pack: any) => {
   221→    if (pack.dodo_product_id) {
   222→      try {
   223→        const v = await syncDodoProduct("verify", { product_id: pack.dodo_product_id });
   224→        if (v.exists) {
   225→          await syncDodoProduct("reactivate", { product_id: pack.dodo_product_id, credit_entitlement_id: pack.dodo_credit_entitlement_id });
   226→        } else {
   227→          await supabase.from("credit_packs").update({ dodo_product_id: null, dodo_credit_entitlement_id: null }).eq("id", pack.id);
   228→          toast.info("Stale Dodo link cleared — you can re-sync after restore.");
   229→        }
   230→      } catch { /* continue */ }
   231→    }
   232→    const { error } = await supabase.from("credit_packs").update({ active: true }).eq("id", pack.id);
   233→    if (error) { toast.error(error.message); return; }
   234→    toast.success(`"${pack.name}" restored`);
   235→    logAuditAction("credit_pack.restore", "credit_pack", pack.id, { name: pack.name });
   236→    qc.invalidateQueries({ queryKey: ["admin_credit_packs"] });
   237→  };
   238→
   239→  const confirmDelete = async () => {
   240→    if (!deleteTarget) return;
   241→    const count = paymentCounts?.[deleteTarget.id] || 0;
   242→    if (count > 0) {
   243→      toast.error(`Cannot delete — this pack has ${count} payment(s) linked. It will remain archived.`);
   244→      setDeleteTarget(null);
   245→      return;
   246→    }
   247→    if (deleteTarget.dodo_product_id) {
   248→      try { await syncDodoProduct("deactivate", { product_id: deleteTarget.dodo_product_id, credit_entitlement_id: deleteTarget.dodo_credit_entitlement_id }); } catch { /* continue */ }
   249→    }
   250→    const { error } = await supabase.from("credit_packs").delete().eq("id", deleteTarget.id);
   251→    if (error) {
   252→      const code = (error as any)?.code;
   253→      if (code === "23503") toast.error("Cannot delete — this pack has existing payments linked to it.");
   254→      else toast.error((error as any)?.message || "Failed to delete");
   255→      setDeleteTarget(null);
   256→      return;
   257→    }
   258→    toast.success("Credit pack permanently deleted");
   259→    logAuditAction("credit_pack.delete", "credit_pack", deleteTarget.id, { name: deleteTarget.name });
   260→    qc.invalidateQueries({ queryKey: ["admin_credit_packs"] });
   261→    setDeleteTarget(null);
   262→  };
   263→
   264→  const DodoBadge = ({ p }: { p: any }) => {
   265→    const vr = verifyResults[p.dodo_product_id];
   266→    if (!p.dodo_product_id) {
   267→      return (
   268→        <Button variant="ghost" size="sm" className="h-6 px-2 gap-1 text-[10px]" onClick={() => handleSyncToDodo(p)} disabled={saving}>
   269→          <Link2 className="h-3 w-3 text-amber-500" />
   270→          <span className="text-muted-foreground">Sync to Dodo</span>
   271→        </Button>
   272→      );
   273→    }
   274→    return (
   275→      <Button variant="ghost" size="sm" className="h-6 px-2 gap-1 text-[10px]" onClick={() => handleVerify(p.id, p.dodo_product_id)} disabled={verifying === p.dodo_product_id}>
   276→        {verifying === p.dodo_product_id ? <Loader2 className="h-3 w-3 animate-spin" /> :
   277→          vr ? (vr.exists && vr.is_active ? <CheckCircle className="h-3 w-3 text-emerald-600" /> : <AlertTriangle className="h-3 w-3 text-amber-500" />) :
   278→          <CheckCircle className="h-3 w-3 text-emerald-600" />}
   279→        <span>{vr ? (vr.exists && vr.is_active ? "Verified ✓" : vr.exists ? "Inactive" : "Not found") : "Linked"}</span>
   280→        <RefreshCw className="h-2.5 w-2.5 text-muted-foreground" />
   281→      </Button>
   282→    );
   283→  };
   284→
   285→  const PackRow = ({ p, archived = false }: { p: any; archived?: boolean }) => {
   286→    const count = paymentCounts?.[p.id] || 0;
   287→    return (
   288→      <TableRow key={p.id} className={archived ? "opacity-60" : ""}>
   289→        <TableCell className="font-medium">
   290→          <div className="flex items-center gap-2">
   291→            {p.name}
   292→            {archived && <Badge variant="outline" className="text-[10px] text-muted-foreground">Archived</Badge>}
   293→          </div>
   294→        </TableCell>
   295→        <TableCell>${p.price}</TableCell>
   296→        <TableCell>{p.credits}</TableCell>
   297→        <TableCell>
   298→          {p.is_trial ? (
   299→            <Badge className="bg-gradient-to-r from-primary to-amber-500 text-primary-foreground border-0 text-[10px] gap-1">
   300→              <Gift className="h-3 w-3" /> Trial
   301→            </Badge>
   302→          ) : <span className="text-muted-foreground text-xs">Regular</span>}
   303→        </TableCell>
   304→        <TableCell><DodoBadge p={p} /></TableCell>
   305→        <TableCell className="flex gap-1">
   306→          {archived ? (
   307→            <>
   308→              <Button variant="ghost" size="icon" title="Restore" onClick={() => handleRestore(p)}>
   309→                <RotateCcw className="h-3.5 w-3.5 text-primary" />
   310→              </Button>
   311→              <Button variant="ghost" size="icon" title={count > 0 ? `${count} payment(s) — cannot delete` : "Delete permanently"} onClick={() => setDeleteTarget({ id: p.id, name: p.name, dodo_product_id: p.dodo_product_id, dodo_credit_entitlement_id: p.dodo_credit_entitlement_id, paymentCount: count })}>
   312→                <Trash2 className={`h-3.5 w-3.5 ${count > 0 ? "text-muted-foreground" : "text-destructive"}`} />
   313→              </Button>
   314→              {count > 0 && <span className="text-[10px] text-destructive self-center">{count} payments</span>}
   315→            </>
   316→          ) : (
   317→            <>
   318→              <Button variant="ghost" size="icon" onClick={() => openEdit(p)}><Pencil className="h-3.5 w-3.5" /></Button>
   319→              <Button variant="ghost" size="icon" title="Archive" onClick={() => handleArchive(p)}>
   320→                <Archive className="h-3.5 w-3.5 text-muted-foreground" />
   321→              </Button>
   322→            </>
   323→          )}
   324→        </TableCell>
   325→      </TableRow>
   326→    );
   327→  };
   328→
   329→  return (
   330→    <>
   331→      <Card>
   332→        <CardHeader className="flex flex-row items-center justify-between pb-3">
   333→          <CardTitle className="text-lg">Credit Packs</CardTitle>
   334→          <Dialog open={editPack !== null} onOpenChange={(o) => !o && setEditPack(null)}>
   335→            <DialogTrigger asChild>
   336→              <Button size="sm" onClick={openNew}><Plus className="h-4 w-4 mr-1" />Add Pack</Button>
   337→            </DialogTrigger>
   338→            <DialogContent aria-describedby="credit-pack-dialog-desc">
   339→              <DialogHeader>
   340→                <DialogTitle>{editPack === "new" ? "New Credit Pack" : "Edit Credit Pack"}</DialogTitle>
   341→                <DialogDescription id="credit-pack-dialog-desc">
   342→                  {editPack === "new" ? "Create a new credit pack synced with Dodo Payments." : "Update this credit pack. Changes sync automatically with Dodo."}
   343→                </DialogDescription>
   344→              </DialogHeader>
   345→              <div className="space-y-3">
   346→                <div><Label>Name</Label><Input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="e.g. Starter Pack" /></div>
   347→                <div className="grid grid-cols-2 gap-3">
   348→                  <div><Label>Price ($)</Label><Input type="number" min="0" step="0.01" value={form.price} onChange={(e) => setForm({ ...form, price: e.target.value })} /></div>
   349→                  <div><Label>Credits</Label><Input type="number" min="1" value={form.credits} onChange={(e) => setForm({ ...form, credits: e.target.value })} /></div>
   350→                </div>
   351→                <div className="flex items-center gap-2"><Switch checked={form.active} onCheckedChange={(c) => setForm({ ...form, active: c })} /><Label>Active</Label></div>
   352→                <div className="flex items-center gap-2">
   353→                  <Switch checked={form.is_trial} onCheckedChange={(c) => setForm({ ...form, is_trial: c })} />
   354→                  <Label className="flex items-center gap-1.5"><Gift className="h-3.5 w-3.5 text-amber-500" />Trial Pack</Label>
   355→                </div>
   356→                {form.is_trial && (
   357→                  <p className="text-xs text-muted-foreground bg-amber-500/10 rounded-md px-3 py-2">
   358→                    Trial packs are only visible to users who haven't made any purchase yet. Only one active trial pack is allowed.
   359→                  </p>
   360→                )}
   361→
   362→                {editPack && editPack !== "new" && (editPack.dodo_product_id || editPack.dodo_credit_entitlement_id) && (
   363→                  <div className="bg-muted/50 rounded-md px-3 py-2 space-y-1">
   364→                    <p className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider">Dodo Integration</p>
   365→                    {editPack.dodo_product_id && (
   366→                      <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
   367→                        <span>Product:</span>
   368→                        <code className="bg-background px-1.5 py-0.5 rounded text-[10px] font-mono">{editPack.dodo_product_id}</code>
   369→                        <a href={`https://app.dodopayments.com/products/${editPack.dodo_product_id}`} target="_blank" rel="noopener noreferrer">
   370→                          <ExternalLink className="h-3 w-3 text-primary" />
   371→                        </a>
   372→                      </div>
   373→                    )}
   374→                    {editPack.dodo_credit_entitlement_id && (
   375→                      <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
   376→                        <span>Credit Entitlement:</span>
   377→                        <code className="bg-background px-1.5 py-0.5 rounded text-[10px] font-mono">{editPack.dodo_credit_entitlement_id}</code>
   378→                      </div>
   379→                    )}
   380→                  </div>
   381→                )}
   382→
   383→                <p className="text-xs text-muted-foreground bg-muted rounded-md px-3 py-2">
   384→                  Dodo product will be auto-created/synced when you save. Brand "Rankora" is auto-attached.
   385→                </p>
   386→                <Button onClick={save} className="w-full" disabled={saving}>
   387→                  {saving ? <Loader2 className="h-4 w-4 mr-1 animate-spin" /> : <Save className="h-4 w-4 mr-1" />}
   388→                  {saving ? "Saving & Syncing..." : "Save"}
   389→                </Button>
   390→              </div>
   391→            </DialogContent>
   392→          </Dialog>
   393→        </CardHeader>
   394→        <CardContent className="p-0">
   395→          <Table>
   396→            <TableHeader>
   397→              <TableRow>
   398→                <TableHead>Name</TableHead>
   399→                <TableHead>Price</TableHead>
   400→                <TableHead>Credits</TableHead>
   401→                <TableHead>Type</TableHead>
   402→                <TableHead>Dodo</TableHead>
   403→                <TableHead></TableHead>
   404→              </TableRow>
