import { useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Switch } from "@/components/ui/switch";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Badge } from "@/components/ui/badge";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { toast } from "sonner";
import { Plus, Pencil, Save, Trash2, Loader2, Gift, CheckCircle, AlertTriangle, Archive, RotateCcw, RefreshCw, Link2, ExternalLink, ChevronDown, Info } from "lucide-react";
import ConfirmDialog from "./ConfirmDialog";
import { logAuditAction } from "@/lib/auditLog";

const parseFunctionError = (error: any) => {
  const message = error?.message || "";
  const jsonStart = message.indexOf("{");
  if (jsonStart === -1) return null;
  try {
    return JSON.parse(message.slice(jsonStart));
  } catch {
    return null;
  }
};

const syncDodoProduct = async (action: string, payload: any) => {
  const { data, error } = await supabase.functions.invoke("manage-dodo-product", {
    body: { action, type: "credit_pack", ...payload },
  });

  if (error) {
    const parsed = parseFunctionError(error);
    if (parsed?.not_found) return parsed;
    throw error;
  }

  if (data?.not_found) return data;
  if (data?.error) throw new Error(data.error);
  return data;
};

type FormState = {
  name: string;
  price: string;
  credits: string;
  active: boolean;
  is_trial: boolean;
  dodo_product_id_input: string;
  dodo_credit_entitlement_id_input: string;
};

const EMPTY_FORM: FormState = {
  name: "",
  price: "",
  credits: "",
  active: true,
  is_trial: false,
  dodo_product_id_input: "",
  dodo_credit_entitlement_id_input: "",
};

const SETUP_STEPS = [
  { step: 1, text: 'Log in to app.dodopayments.com → Products → Create New Product' },
  { step: 2, text: 'Set Name (e.g. "100 Credits — $10"), Price (one-time), Tax Category: SaaS' },
  { step: 3, text: 'Copy the Product ID (starts with prod_) from the product detail page' },
  { step: 4, text: 'Under "Credit Entitlements" tab, create an entitlement: Name: "$10 - 100 Credits" | Unit: credits | Rollover: disabled' },
  { step: 5, text: 'Copy the Credit Entitlement ID (starts with ce_)' },
  { step: 6, text: 'Paste both IDs into the fields above and click "Verify & Link"' },
  { step: 7, text: 'Save the pack — the app will verify the product exists and link it' },
];

const FIELD_MAP = [
  { field: "Name", dodo: "Product name in Dodo dashboard" },
  { field: "Price ($)", dodo: "One-time product price" },
  { field: "Credits", dodo: "Credit entitlement amount" },
  { field: "Dodo Product ID", dodo: "prod_xxxx from product detail page" },
  { field: "Dodo Credit Entitlement ID", dodo: "ce_xxxx from entitlement tab" },
];

const CreditPacksTab = () => {
  const qc = useQueryClient();
  const [saving, setSaving] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<{ id: string; name: string; dodo_product_id?: string; dodo_credit_entitlement_id?: string; paymentCount?: number } | null>(null);
  const [showArchived, setShowArchived] = useState(false);
  const [verifying, setVerifying] = useState<string | null>(null);
  const [verifyResults, setVerifyResults] = useState<Record<string, { exists: boolean; is_active?: boolean }>>({});
  const [dialogVerifying, setDialogVerifying] = useState(false);
  const [dialogVerifyResult, setDialogVerifyResult] = useState<{ exists: boolean; is_active?: boolean; name?: string } | null>(null);
  const [showSetupGuide, setShowSetupGuide] = useState(false);
  const [showQuickRef, setShowQuickRef] = useState(false);

  const { data: packs } = useQuery({
    queryKey: ["admin_credit_packs"],
    queryFn: async () => {
      const { data, error } = await supabase.from("credit_packs").select("*").order("created_at");
      if (error) throw error;
      return data;
    },
  });

  const { data: paymentCounts } = useQuery({
    queryKey: ["admin_pack_payment_counts"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("payments")
        .select("pack_id")
        .not("pack_id", "is", null);
      if (error) throw error;
      const counts: Record<string, number> = {};
      data?.forEach((p: any) => { counts[p.pack_id] = (counts[p.pack_id] || 0) + 1; });
      return counts;
    },
  });

  const activePacks = packs?.filter((p: any) => p.active) ?? [];
  const archivedPacks = packs?.filter((p: any) => !p.active) ?? [];

  const [editPack, setEditPack] = useState<any>(null);
  const [form, setForm] = useState<FormState>(EMPTY_FORM);

  const openNew = () => {
    setForm(EMPTY_FORM);
    setDialogVerifyResult(null);
    setEditPack("new");
  };

  const openEdit = (p: any) => {
    setForm({
      name: p.name,
      price: String(p.price),
      credits: String(p.credits),
      active: p.active,
      is_trial: p.is_trial ?? false,
      dodo_product_id_input: p.dodo_product_id ?? "",
      dodo_credit_entitlement_id_input: p.dodo_credit_entitlement_id ?? "",
    });
    setDialogVerifyResult(null);
    setEditPack(p);
  };

  const validate = () => {
    if (!form.name.trim()) { toast.error("Pack name is required"); return false; }
    if (!form.price || parseFloat(form.price) < 0) { toast.error("Price must be 0 or greater"); return false; }
    if (!form.credits || parseInt(form.credits) <= 0) { toast.error("Credits must be greater than 0"); return false; }
    if (form.is_trial && form.active) {
      const existingTrial = packs?.find((p: any) => p.is_trial && p.active && (editPack === "new" || p.id !== editPack?.id));
      if (existingTrial) { toast.error("Only one active trial pack is allowed."); return false; }
    }
    return true;
  };

  const handleVerify = async (packId: string, productId: string) => {
    setVerifying(productId);
    try {
      const result = await syncDodoProduct("verify", { product_id: productId });
      setVerifyResults(prev => ({ ...prev, [productId]: result }));
      if (result.exists && result.is_active) {
        toast.success("Product verified on Dodo ✓");
      } else if (result.exists) {
        toast.warning("Product exists on Dodo but is inactive");
      } else {
        // Auto-clear stale Dodo ID from DB
        await supabase.from("credit_packs").update({ dodo_product_id: null, dodo_credit_entitlement_id: null }).eq("id", packId);
        qc.invalidateQueries({ queryKey: ["admin_credit_packs"] });
        toast.error("Product not found on Dodo — link cleared automatically");
      }
    } catch (err: any) {
      toast.error("Verify failed: " + (err.message || "Unknown error"));
    } finally { setVerifying(null); }
  };

  const handleDialogVerifyAndLink = async () => {
    const productId = form.dodo_product_id_input.trim();
    if (!productId) { toast.error("Enter a Product ID first"); return; }
    setDialogVerifying(true);
    setDialogVerifyResult(null);
    try {
      const result = await syncDodoProduct("verify", { product_id: productId });
      setDialogVerifyResult(result);

      if (result.exists) {
        // If editing an existing pack, update DB immediately
        if (editPack && editPack !== "new") {
          await supabase.from("credit_packs").update({
            dodo_product_id: productId,
            dodo_credit_entitlement_id: form.dodo_credit_entitlement_id_input.trim() || null,
          }).eq("id", editPack.id);
          qc.invalidateQueries({ queryKey: ["admin_credit_packs"] });
          toast.success("Linked to existing Dodo product ✓");
        } else {
          toast.success("Product found on Dodo — will be linked on save ✓");
        }
      } else {
        toast.error("Product not found on Dodo — check the Product ID");
      }
    } catch (err: any) {
      toast.error("Verify failed: " + (err.message || "Unknown error"));
    } finally { setDialogVerifying(false); }
  };

  const handleSyncToDodo = async (pack: any) => {
    setSaving(true);
    try {
      const dodoResult = await syncDodoProduct("create", { name: pack.name, price: pack.price, credits: pack.credits });
      if (dodoResult.product_id) {
        const updateData: any = { dodo_product_id: dodoResult.product_id };
        if (dodoResult.credit_entitlement_id) updateData.dodo_credit_entitlement_id = dodoResult.credit_entitlement_id;
        await supabase.from("credit_packs").update(updateData).eq("id", pack.id);
        toast.success("Pack synced with Dodo ✓");
        qc.invalidateQueries({ queryKey: ["admin_credit_packs"] });
      }
    } catch (err: any) {
      toast.error("Dodo sync failed: " + (err.message || "Unknown error"));
    } finally { setSaving(false); }
  };

  const save = async () => {
    if (!validate()) return;
    setSaving(true);
    try {
      const payload = {
        name: form.name.trim(),
        price: parseFloat(form.price),
        credits: parseInt(form.credits),
        active: form.active,
        is_trial: form.is_trial,
      } as any;

      const manualProductId = form.dodo_product_id_input.trim();
      const manualEntitlementId = form.dodo_credit_entitlement_id_input.trim();

      if (editPack === "new") {
        if (manualProductId) {
          // Manual link mode — insert with provided IDs, then verify
          const insertPayload = {
            ...payload,
            dodo_product_id: manualProductId,
            dodo_credit_entitlement_id: manualEntitlementId || null,
          };
          const { data: inserted, error } = await supabase.from("credit_packs").insert(insertPayload).select().single();
          if (error) { toast.error(error.message); return; }
          try {
            const verifyResult = await syncDodoProduct("verify", { product_id: manualProductId });
            if (verifyResult.exists) {
              toast.success("Credit pack saved & linked to existing Dodo product ✓");
            } else {
              toast.warning("Pack saved but Dodo product not found — verify the Product ID");
            }
            setDialogVerifyResult(verifyResult);
          } catch (verifyErr: any) {
            toast.warning("Pack saved but Dodo verify failed: " + (verifyErr.message || "Unknown error"));
          }
        } else {
          // Auto-create mode — original behaviour
          const { data: inserted, error } = await supabase.from("credit_packs").insert(payload).select().single();
          if (error) { toast.error(error.message); return; }
          try {
            const dodoResult = await syncDodoProduct("create", { name: form.name.trim(), price: parseFloat(form.price), credits: parseInt(form.credits) });
            if (dodoResult.product_id) {
              const updateData: any = { dodo_product_id: dodoResult.product_id };
              if (dodoResult.credit_entitlement_id) updateData.dodo_credit_entitlement_id = dodoResult.credit_entitlement_id;
              await supabase.from("credit_packs").update(updateData).eq("id", inserted.id);
              toast.success("Credit pack saved & synced with Dodo ✓");
            } else toast.success("Credit pack saved (no Dodo product ID returned)");
          } catch (dodoErr: any) {
            toast.warning("Pack saved locally but Dodo sync failed: " + (dodoErr.message || "Unknown error"));
          }
        }
      } else {
        const { error } = await supabase.from("credit_packs").update(payload).eq("id", editPack.id);
        if (error) { toast.error(error.message); return; }

        if (manualProductId && manualProductId !== editPack.dodo_product_id) {
          // User provided new manual IDs — update and verify
          await supabase.from("credit_packs").update({
            dodo_product_id: manualProductId,
            dodo_credit_entitlement_id: manualEntitlementId || null,
          }).eq("id", editPack.id);
          try {
            const verifyResult = await syncDodoProduct("verify", { product_id: manualProductId });
            if (verifyResult.exists) {
              toast.success("Pack updated & linked to existing Dodo product ✓");
            } else {
              toast.warning("Pack updated but Dodo product not found — verify the Product ID");
            }
          } catch (verifyErr: any) {
            toast.warning("Pack updated but Dodo verify failed: " + (verifyErr.message || "Unknown error"));
          }
        } else if (editPack.dodo_product_id) {
          try {
            const verification = await syncDodoProduct("verify", { product_id: editPack.dodo_product_id });

            if (!verification.exists) {
              await supabase.from("credit_packs").update({ dodo_product_id: null, dodo_credit_entitlement_id: null }).eq("id", editPack.id);
              const recreated = await syncDodoProduct("create", {
                name: form.name.trim(),
                price: parseFloat(form.price),
                credits: parseInt(form.credits),
              });
              if (recreated.product_id) {
                const updateData: any = { dodo_product_id: recreated.product_id };
                if (recreated.credit_entitlement_id) updateData.dodo_credit_entitlement_id = recreated.credit_entitlement_id;
                await supabase.from("credit_packs").update(updateData).eq("id", editPack.id);
              }
              toast.success("Missing Dodo product was re-created and linked ✓");
            } else {
              const dodoResult = await syncDodoProduct("update", { product_id: editPack.dodo_product_id, name: form.name.trim(), price: parseFloat(form.price), credits: parseInt(form.credits) });
              if (dodoResult.credit_entitlement_id) {
                await supabase.from("credit_packs").update({ dodo_credit_entitlement_id: dodoResult.credit_entitlement_id }).eq("id", editPack.id);
              }
              toast.success("Pack updated & synced with Dodo ✓");
            }
          } catch (dodoErr: any) {
            toast.warning("Pack updated locally but Dodo sync failed: " + (dodoErr.message || "Unknown error"));
          }
        } else {
          try {
            const dodoResult = await syncDodoProduct("create", { name: form.name.trim(), price: parseFloat(form.price), credits: parseInt(form.credits) });
            if (dodoResult.product_id) {
              const updateData: any = { dodo_product_id: dodoResult.product_id };
              if (dodoResult.credit_entitlement_id) updateData.dodo_credit_entitlement_id = dodoResult.credit_entitlement_id;
              await supabase.from("credit_packs").update(updateData).eq("id", editPack.id);
              toast.success("Pack updated & linked to Dodo ✓");
            } else toast.success("Pack updated");
          } catch (dodoErr: any) {
            toast.warning("Pack updated but Dodo link failed: " + (dodoErr.message || "Unknown error"));
          }
        }
      }

      logAuditAction(editPack === "new" ? "credit_pack.create" : "credit_pack.update", "credit_pack", editPack === "new" ? undefined : editPack.id, { name: form.name, price: form.price, credits: form.credits, is_trial: form.is_trial });
      qc.invalidateQueries({ queryKey: ["admin_credit_packs"] });
      setEditPack(null);
    } finally { setSaving(false); }
  };

  const handleArchive = async (pack: any) => {
    if (pack.dodo_product_id) {
      try {
        const v = await syncDodoProduct("verify", { product_id: pack.dodo_product_id });
        if (v.exists) {
          await syncDodoProduct("deactivate", { product_id: pack.dodo_product_id, credit_entitlement_id: pack.dodo_credit_entitlement_id });
        } else {
          await supabase.from("credit_packs").update({ dodo_product_id: null, dodo_credit_entitlement_id: null }).eq("id", pack.id);
        }
      } catch { /* continue */ }
    }
    const { error } = await supabase.from("credit_packs").update({ active: false }).eq("id", pack.id);
    if (error) { toast.error(error.message); return; }
    toast.success(`"${pack.name}" archived`);
    logAuditAction("credit_pack.archive", "credit_pack", pack.id, { name: pack.name });
    qc.invalidateQueries({ queryKey: ["admin_credit_packs"] });
  };

  const handleRestore = async (pack: any) => {
    if (pack.dodo_product_id) {
      try {
        const v = await syncDodoProduct("verify", { product_id: pack.dodo_product_id });
        if (v.exists) {
          await syncDodoProduct("reactivate", { product_id: pack.dodo_product_id, credit_entitlement_id: pack.dodo_credit_entitlement_id });
        } else {
          await supabase.from("credit_packs").update({ dodo_product_id: null, dodo_credit_entitlement_id: null }).eq("id", pack.id);
          toast.info("Stale Dodo link cleared — you can re-sync after restore.");
        }
      } catch { /* continue */ }
    }
    const { error } = await supabase.from("credit_packs").update({ active: true }).eq("id", pack.id);
    if (error) { toast.error(error.message); return; }
    toast.success(`"${pack.name}" restored`);
    logAuditAction("credit_pack.restore", "credit_pack", pack.id, { name: pack.name });
    qc.invalidateQueries({ queryKey: ["admin_credit_packs"] });
  };

  const confirmDelete = async () => {
    if (!deleteTarget) return;
    const count = paymentCounts?.[deleteTarget.id] || 0;
    if (count > 0) {
      toast.error(`Cannot delete — this pack has ${count} payment(s) linked. It will remain archived.`);
      setDeleteTarget(null);
      return;
    }
    if (deleteTarget.dodo_product_id) {
      try { await syncDodoProduct("deactivate", { product_id: deleteTarget.dodo_product_id, credit_entitlement_id: deleteTarget.dodo_credit_entitlement_id }); } catch { /* continue */ }
    }
    const { error } = await supabase.from("credit_packs").delete().eq("id", deleteTarget.id);
    if (error) {
      const code = (error as any)?.code;
      if (code === "23503") toast.error("Cannot delete — this pack has existing payments linked to it.");
      else toast.error((error as any)?.message || "Failed to delete");
      setDeleteTarget(null);
      return;
    }
    toast.success("Credit pack permanently deleted");
    logAuditAction("credit_pack.delete", "credit_pack", deleteTarget.id, { name: deleteTarget.name });
    qc.invalidateQueries({ queryKey: ["admin_credit_packs"] });
    setDeleteTarget(null);
  };

  const DodoBadge = ({ p }: { p: any }) => {
    const vr = verifyResults[p.dodo_product_id];
    if (!p.dodo_product_id) {
      return (
        <Button variant="ghost" size="sm" className="h-6 px-2 gap-1 text-[10px]" onClick={() => handleSyncToDodo(p)} disabled={saving}>
          <Link2 className="h-3 w-3 text-amber-500" />
          <span className="text-muted-foreground">Sync to Dodo</span>
        </Button>
      );
    }
    return (
      <Button variant="ghost" size="sm" className="h-6 px-2 gap-1 text-[10px]" onClick={() => handleVerify(p.id, p.dodo_product_id)} disabled={verifying === p.dodo_product_id}>
        {verifying === p.dodo_product_id ? <Loader2 className="h-3 w-3 animate-spin" /> :
          vr ? (vr.exists && vr.is_active ? <CheckCircle className="h-3 w-3 text-emerald-600" /> : <AlertTriangle className="h-3 w-3 text-amber-500" />) :
          <CheckCircle className="h-3 w-3 text-emerald-600" />}
        <span>{vr ? (vr.exists && vr.is_active ? "Verified ✓" : vr.exists ? "Inactive" : "Not found") : "Linked"}</span>
        <RefreshCw className="h-2.5 w-2.5 text-muted-foreground" />
      </Button>
    );
  };

  const PackRow = ({ p, archived = false }: { p: any; archived?: boolean }) => {
    const count = paymentCounts?.[p.id] || 0;
    return (
      <TableRow key={p.id} className={archived ? "opacity-60" : ""}>
        <TableCell className="font-medium">
          <div className="flex items-center gap-2">
            {p.name}
            {archived && <Badge variant="outline" className="text-[10px] text-muted-foreground">Archived</Badge>}
          </div>
        </TableCell>
        <TableCell>${p.price}</TableCell>
        <TableCell>{p.credits}</TableCell>
        <TableCell>
          {p.is_trial ? (
            <Badge className="bg-gradient-to-r from-primary to-amber-500 text-primary-foreground border-0 text-[10px] gap-1">
              <Gift className="h-3 w-3" /> Trial
            </Badge>
          ) : <span className="text-muted-foreground text-xs">Regular</span>}
        </TableCell>
        <TableCell><DodoBadge p={p} /></TableCell>
        <TableCell className="flex gap-1">
          {archived ? (
            <>
              <Button variant="ghost" size="icon" title="Restore" onClick={() => handleRestore(p)}>
                <RotateCcw className="h-3.5 w-3.5 text-primary" />
              </Button>
              <Button variant="ghost" size="icon" title={count > 0 ? `${count} payment(s) — cannot delete` : "Delete permanently"} onClick={() => setDeleteTarget({ id: p.id, name: p.name, dodo_product_id: p.dodo_product_id, dodo_credit_entitlement_id: p.dodo_credit_entitlement_id, paymentCount: count })}>
                <Trash2 className={`h-3.5 w-3.5 ${count > 0 ? "text-muted-foreground" : "text-destructive"}`} />
              </Button>
              {count > 0 && <span className="text-[10px] text-destructive self-center">{count} payments</span>}
            </>
          ) : (
            <>
              <Button variant="ghost" size="icon" onClick={() => openEdit(p)}><Pencil className="h-3.5 w-3.5" /></Button>
              <Button variant="ghost" size="icon" title="Archive" onClick={() => handleArchive(p)}>
                <Archive className="h-3.5 w-3.5 text-muted-foreground" />
              </Button>
            </>
          )}
        </TableCell>
      </TableRow>
    );
  };

  const hasManualIds = form.dodo_product_id_input.trim().length > 0 || form.dodo_credit_entitlement_id_input.trim().length > 0;
  const canDialogVerify = form.dodo_product_id_input.trim().length > 0 && editPack && editPack !== "new";

  return (
    <>
      <Card>
        <CardHeader className="flex flex-row items-center justify-between pb-3">
          <CardTitle className="text-lg">Credit Packs</CardTitle>
          <Dialog open={editPack !== null} onOpenChange={(o) => !o && setEditPack(null)}>
            <DialogTrigger asChild>
              <Button size="sm" onClick={openNew}><Plus className="h-4 w-4 mr-1" />Add Pack</Button>
            </DialogTrigger>
            <DialogContent aria-describedby="credit-pack-dialog-desc" className="max-w-lg max-h-[90vh] overflow-y-auto">
              <DialogHeader>
                <DialogTitle>{editPack === "new" ? "New Credit Pack" : "Edit Credit Pack"}</DialogTitle>
                <DialogDescription id="credit-pack-dialog-desc">
                  {editPack === "new" ? "Create a new credit pack synced with Dodo Payments." : "Update this credit pack. Changes sync automatically with Dodo."}
                </DialogDescription>
              </DialogHeader>
              <div className="space-y-3">
                <div><Label>Name</Label><Input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="e.g. Starter Pack" /></div>
                <div className="grid grid-cols-2 gap-3">
                  <div><Label>Price ($)</Label><Input type="number" min="0" step="0.01" value={form.price} onChange={(e) => setForm({ ...form, price: e.target.value })} /></div>
                  <div><Label>Credits</Label><Input type="number" min="1" value={form.credits} onChange={(e) => setForm({ ...form, credits: e.target.value })} /></div>
                </div>
                <div className="flex items-center gap-2"><Switch checked={form.active} onCheckedChange={(c) => setForm({ ...form, active: c })} /><Label>Active</Label></div>
                <div className="flex items-center gap-2">
                  <Switch checked={form.is_trial} onCheckedChange={(c) => setForm({ ...form, is_trial: c })} />
                  <Label className="flex items-center gap-1.5"><Gift className="h-3.5 w-3.5 text-amber-500" />Trial Pack</Label>
                </div>
                {form.is_trial && (
                  <p className="text-xs text-muted-foreground bg-amber-500/10 rounded-md px-3 py-2">
                    Trial packs are only visible to users who haven't made any purchase yet. Only one active trial pack is allowed.
                  </p>
                )}

                {/* Manual Dodo Link section */}
                <div className="border rounded-md p-3 space-y-3 bg-muted/30">
                  <div className="flex items-center gap-1.5">
                    <Link2 className="h-3.5 w-3.5 text-primary" />
                    <span className="text-xs font-medium">Manual Dodo Link</span>
                  </div>
                  <p className="text-[11px] text-muted-foreground leading-relaxed">
                    Fill these only if you already created the product in Dodo manually. Leave blank to auto-create.
                  </p>

                  <div className="space-y-1">
                    <Label className="text-xs">Dodo Product ID (manual link)</Label>
                    <div className="flex gap-2">
                      <Input
                        value={form.dodo_product_id_input}
                        onChange={(e) => { setForm({ ...form, dodo_product_id_input: e.target.value }); setDialogVerifyResult(null); }}
                        placeholder="prod_xxxxxxxxxxxx"
                        className="font-mono text-xs"
                      />
                      {canDialogVerify && (
                        <Button
                          type="button"
                          size="sm"
                          variant="outline"
                          onClick={handleDialogVerifyAndLink}
                          disabled={dialogVerifying}
                          className="shrink-0"
                        >
                          {dialogVerifying ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <CheckCircle className="h-3.5 w-3.5" />}
                          <span className="ml-1 text-xs">Verify & Link</span>
                        </Button>
                      )}
                    </div>
                  </div>

                  <div className="space-y-1">
                    <Label className="text-xs">Dodo Credit Entitlement ID (optional)</Label>
                    <Input
                      value={form.dodo_credit_entitlement_id_input}
                      onChange={(e) => setForm({ ...form, dodo_credit_entitlement_id_input: e.target.value })}
                      placeholder="ce_xxxxxxxxxxxx"
                      className="font-mono text-xs"
                    />
                  </div>

                  {/* Inline verify result */}
                  {dialogVerifyResult && (
                    <div className={`flex items-center gap-2 rounded-md px-3 py-2 text-xs ${dialogVerifyResult.exists ? "bg-emerald-500/10 text-emerald-700 dark:text-emerald-400" : "bg-destructive/10 text-destructive"}`}>
                      {dialogVerifyResult.exists ? (
                        <>
                          <CheckCircle className="h-3.5 w-3.5 shrink-0" />
                          <span>
                            Product found on Dodo
                            {dialogVerifyResult.name ? ` — "${dialogVerifyResult.name}"` : ""}
                            {dialogVerifyResult.is_active ? " (active)" : " (inactive)"}
                          </span>
                        </>
                      ) : (
                        <>
                          <AlertTriangle className="h-3.5 w-3.5 shrink-0" />
                          <span>Product not found on Dodo — double-check the Product ID</span>
                        </>
                      )}
                    </div>
                  )}

                  {editPack && editPack !== "new" && (editPack.dodo_product_id || editPack.dodo_credit_entitlement_id) && !hasManualIds && (
                    <div className="space-y-1 pt-1 border-t">
                      <p className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider">Currently Linked</p>
                      {editPack.dodo_product_id && (
                        <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
                          <span>Product:</span>
                          <code className="bg-background px-1.5 py-0.5 rounded text-[10px] font-mono">{editPack.dodo_product_id}</code>
                          <a href={`https://app.dodopayments.com/products/${editPack.dodo_product_id}`} target="_blank" rel="noopener noreferrer">
                            <ExternalLink className="h-3 w-3 text-primary" />
                          </a>
                        </div>
                      )}
                      {editPack.dodo_credit_entitlement_id && (
                        <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
                          <span>Credit Entitlement:</span>
                          <code className="bg-background px-1.5 py-0.5 rounded text-[10px] font-mono">{editPack.dodo_credit_entitlement_id}</code>
                        </div>
                      )}
                    </div>
                  )}
                </div>

                <p className="text-xs text-muted-foreground bg-muted rounded-md px-3 py-2">
                  Dodo product will be auto-created/synced when you save (if no manual IDs are provided). Brand "Rankora" is auto-attached.
                </p>

                {/* Setup Guide — collapsible */}
                <Collapsible open={showSetupGuide} onOpenChange={setShowSetupGuide}>
                  <CollapsibleTrigger asChild>
                    <button className="w-full flex items-center justify-between rounded-md border px-3 py-2 text-xs font-medium text-muted-foreground hover:text-foreground hover:bg-muted/50 transition-colors">
                      <span className="flex items-center gap-1.5">
                        <Info className="h-3.5 w-3.5" />
                        Setup Guide — How to connect a Dodo product
                      </span>
                      <ChevronDown className={`h-3.5 w-3.5 transition-transform ${showSetupGuide ? "rotate-180" : ""}`} />
                    </button>
                  </CollapsibleTrigger>
                  <CollapsibleContent className="mt-2 space-y-2">
                    <div className="rounded-md border bg-muted/20 p-3 space-y-2">
                      {SETUP_STEPS.map(({ step, text }) => (
                        <div key={step} className="flex gap-2.5 text-[11px] text-muted-foreground leading-relaxed">
                          <span className="shrink-0 flex h-4 w-4 items-center justify-center rounded-full bg-primary/10 text-primary text-[10px] font-bold mt-0.5">{step}</span>
                          <span>{text}</span>
                        </div>
                      ))}
                      <div className="border-t pt-2 mt-2">
                        <p className="text-[11px] text-muted-foreground italic">
                          Note: Credits are tracked by your app (not Dodo) for wallet top-ups. For fixed packs, Dodo credit entitlements track the grant.
                        </p>
                      </div>
                    </div>
                  </CollapsibleContent>
                </Collapsible>

                <Button onClick={save} className="w-full" disabled={saving}>
                  {saving ? <Loader2 className="h-4 w-4 mr-1 animate-spin" /> : <Save className="h-4 w-4 mr-1" />}
                  {saving ? "Saving & Syncing..." : "Save"}
                </Button>
              </div>
            </DialogContent>
          </Dialog>
        </CardHeader>
        <CardContent className="p-0">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Name</TableHead>
                <TableHead>Price</TableHead>
                <TableHead>Credits</TableHead>
                <TableHead>Type</TableHead>
                <TableHead>Dodo</TableHead>
                <TableHead></TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {activePacks.length === 0 && archivedPacks.length === 0 && (
                <TableRow><TableCell colSpan={6} className="text-center text-muted-foreground py-8">No credit packs yet</TableCell></TableRow>
              )}
              {activePacks.map((p: any) => <PackRow key={p.id} p={p} />)}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      {archivedPacks.length > 0 && (
        <Card className="border-dashed">
          <CardHeader className="pb-3">
            <button onClick={() => setShowArchived(!showArchived)} className="flex items-center gap-2 text-sm font-medium text-muted-foreground hover:text-foreground transition-colors">
              <Archive className="h-4 w-4" />
              Archived Packs ({archivedPacks.length})
              <span className="text-xs">{showArchived ? "▾" : "▸"}</span>
            </button>
          </CardHeader>
          {showArchived && (
            <CardContent className="p-0">
              <Table><TableBody>{archivedPacks.map((p: any) => <PackRow key={p.id} p={p} archived />)}</TableBody></Table>
            </CardContent>
          )}
        </Card>
      )}

      {/* Quick Setup Reference card */}
      <Card className="border-dashed border-primary/20">
        <CardHeader className="pb-2">
          <button
            onClick={() => setShowQuickRef(!showQuickRef)}
            className="flex items-center justify-between w-full text-sm font-medium text-muted-foreground hover:text-foreground transition-colors"
          >
            <span className="flex items-center gap-2">
              <Info className="h-4 w-4 text-primary" />
              Quick Setup Reference — Dodo Payments
            </span>
            <ChevronDown className={`h-4 w-4 transition-transform ${showQuickRef ? "rotate-180" : ""}`} />
          </button>
        </CardHeader>
        {showQuickRef && (
          <CardContent className="space-y-4">
            <div>
              <p className="text-xs font-medium text-muted-foreground mb-2 uppercase tracking-wider">Field Mapping</p>
              <div className="rounded-md border overflow-hidden">
                <table className="w-full text-xs">
                  <thead>
                    <tr className="bg-muted/50">
                      <th className="text-left px-3 py-1.5 font-medium text-muted-foreground">App Field</th>
                      <th className="text-left px-3 py-1.5 font-medium text-muted-foreground">Dodo Dashboard</th>
                    </tr>
                  </thead>
                  <tbody>
                    {FIELD_MAP.map(({ field, dodo }) => (
                      <tr key={field} className="border-t">
                        <td className="px-3 py-1.5 font-mono text-[11px]">{field}</td>
                        <td className="px-3 py-1.5 text-muted-foreground">{dodo}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
            <div>
              <p className="text-xs font-medium text-muted-foreground mb-2 uppercase tracking-wider">One-time Setup Checklist</p>
              <ul className="space-y-1 text-xs text-muted-foreground">
                <li className="flex items-start gap-2"><CheckCircle className="h-3.5 w-3.5 text-emerald-500 mt-0.5 shrink-0" />Create product in Dodo with one-time pricing</li>
                <li className="flex items-start gap-2"><CheckCircle className="h-3.5 w-3.5 text-emerald-500 mt-0.5 shrink-0" />Add a Credit Entitlement under the product</li>
                <li className="flex items-start gap-2"><CheckCircle className="h-3.5 w-3.5 text-emerald-500 mt-0.5 shrink-0" />Copy prod_ and ce_ IDs into the pack dialog</li>
                <li className="flex items-start gap-2"><CheckCircle className="h-3.5 w-3.5 text-emerald-500 mt-0.5 shrink-0" />Click "Verify & Link" to confirm the connection</li>
              </ul>
            </div>
            <div className="flex items-center justify-between pt-1 border-t">
              <p className="text-[11px] text-muted-foreground">Manage all Dodo products in the dashboard</p>
              <a
                href="https://app.dodopayments.com"
                target="_blank"
                rel="noopener noreferrer"
                className="flex items-center gap-1 text-xs text-primary hover:underline"
              >
                app.dodopayments.com <ExternalLink className="h-3 w-3" />
              </a>
            </div>
          </CardContent>
        )}
      </Card>

      <ConfirmDialog
        open={deleteTarget !== null}
        onOpenChange={(o) => !o && setDeleteTarget(null)}
        title="Permanently Delete Pack"
        description={
          deleteTarget?.paymentCount && deleteTarget.paymentCount > 0
            ? `Cannot delete "${deleteTarget?.name}" — it has ${deleteTarget.paymentCount} payment(s) linked. It will remain archived.`
            : `Are you sure you want to permanently delete "${deleteTarget?.name}"? This cannot be undone.`
        }
        confirmLabel={deleteTarget?.paymentCount && deleteTarget.paymentCount > 0 ? "Understood" : "Delete Permanently"}
        onConfirm={deleteTarget?.paymentCount && deleteTarget.paymentCount > 0 ? () => setDeleteTarget(null) : confirmDelete}
      />
    </>
  );
};

export default CreditPacksTab;
